// Pseudo
class MG {
  constructor(s){
    this.s = s;
    this.counters = new Map();
  }
  add(x){
    if (this.counters.has(x)) { this.counters.set(x, this.counters.get(x)+1); return; }
    if (this.counters.size < this.s-1) {
      this.counters.set(x, 1);
      return;
    }
    for (let k of Array.from(this.counters.keys())) {
      this.counters.set(k, this.counters.get(k)-1);
      if (this.counters.get(k) === 0) this.counters.delete(k);
    }
  }
  topK(k){
    // return top k by counts
    return [...this.counters.entries()].sort((a,b)=>b[1]-a[1]).slice(0,k);
  }
}
```

